/* Research uses the selected stock and model. Browsing never starts a model call. */
(function(){
 'use strict';
 const $=id=>document.getElementById(id),node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 const wiki=$('wikiPanel');if(!wiki)return;
 const open=node('button','我的研究 · L2');open.id='researchOpen';wiki.querySelector('.wiki-header').append(open);
 const panel=node('section',undefined,'research-panel');panel.id='researchPanel';panel.hidden=true;
 panel.innerHTML=`<header><button id="researchBack" type="button">← 通用觀點 L1</button><h2>我的研究</h2><span id="researchStock"></span></header>
 <div class="research-layout"><aside><h3>追蹤中的問題</h3><div id="researchSaved"></div><details><summary>分類詞彙</summary><div id="researchTaxonomy"></div></details></aside>
 <main><form id="researchForm"><label for="researchQuestion">你想研究什麼？</label><div class="research-query"><input id="researchQuestion" required maxlength="2000" placeholder="例如：資料中心需求與資本支出的風險" autocomplete="off"><button id="researchSubmit" class="wiki-primary">建立研究</button></div>
 <div class="research-options"><label>觀察期間<select id="researchWindow"><option value="30">最近 30 日</option><option value="90">最近 90 日</option><option value="365">最近一年</option></select></label><span id="researchModel"></span></div>
 <details><summary>限定或排除條件</summary><div class="research-options"><label>包含文字<input id="researchInclude" placeholder="符合這個文字才入選"></label><label>排除文字<input id="researchExclude" placeholder="包含這個文字就排除"></label></div><p>兩項同時填入時採 AND；零結果也不會放寬。</p></details></form>
 <p id="researchStatus" role="status" aria-live="polite"></p><section id="researchResult"><p>從既有通用觀點與新聞證據回答問題。建立後可保存為持續追蹤，或固定這次快照。</p></section></main></div>`;
 wiki.append(panel);
 let stock='',serial=0,runId=null,timer=null,graph=null,lastLens=null;
 async function api(path,body){const r=await fetch('/api/wiki/research/'+path+(body===undefined?(path.includes('?')?'&':'?')+'instrument='+encodeURIComponent(stock):''),body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,instrument:stock})});const v=await r.json();if(!r.ok)throw Error(v.error||'研究請求失敗');return v;}
 function status(text){$('researchStatus').textContent=text;}
 function action(text,fn){const b=node('button',text);b.type='button';b.onclick=async()=>{const token=serial;b.disabled=true;try{await fn();}catch(e){if(token===serial)status(e.message);}finally{b.disabled=false;}};return b;}
 function details(title,children){const d=node('details');d.append(node('summary',title),...children);return d;}
 function sourceChain(claim,b){const out=[];for(const ref of claim.derived_from){const o=b.opinions.find(n=>n.claim_id===ref);if(!o)continue;const evidence=o.evidence.map(e=>{const text=node('blockquote',e.quote);const link=node('a',e.provider+' · '+(e.published_at||'日期未知'));if(/^https?:\/\//.test(e.url)){link.href=e.url;link.target='_blank';link.rel='noopener noreferrer';}return details('新聞證據',[text,link]);});out.push(details('L1 · '+o.title,[node('p',o.statement),node('small',o.selection_reason),...evidence]));}return out;}
 function render(r){
  graph?._destructor?.();graph=null;const target=$('researchResult');target.replaceChildren();const b=r.bundle,result=r.result;
  if(r.current_epochs.corpus!==b.manifest.epochs.corpus||r.current_epochs.taxonomy!==b.manifest.epochs.taxonomy)target.append(node('p','來源或觀點已有變更；以下保留原快照，請更新研究後核對。','research-meta'));
  target.append(node('h3',b.lens.normalized_question),node('p',b.lens.instrument+' · '+b.lens.time_spec.start.slice(0,10)+' → '+b.lens.time_spec.end.slice(0,10)+' · '+(result.content_status==='insufficient_evidence'?'證據不足':'有資料限制'),'research-meta'));
  const controls=node('div',undefined,'research-actions');controls.append(action('持續追蹤',async()=>{const token=serial;const savedLens=await api('save',{run_id:runId,mode:'live'});if(token!==serial)return;lastLens=savedLens;status('已保存；新增相關觀點或時間窗移動後會重新檢索。');await saved();}),action('固定快照',async()=>{const token=serial;const savedLens=await api('save',{run_id:runId,mode:'pinned'});if(token!==serial)return;lastLens=savedLens;status('已固定這次條件與結果。');await saved();}));target.append(controls);
  const claims=new Map(result.claims.map(c=>[c.id,c]));
  function section(title,refs){const s=node('section',undefined,'research-section');s.append(node('h3',title));if(!refs.length)s.append(node('p','本次檢索範圍內沒有足夠資料。'));for(const id of refs){const c=claims.get(id);if(!c)continue;const article=node('article');article.append(node('p',c.statement));const extra=[...sourceChain(c,b)];if(c.assumptions.length)extra.push(node('p','假設：'+c.assumptions.join('；')));if(c.invalidating_conditions.length)extra.push(node('p','失效條件：'+c.invalidating_conditions.join('；')));article.append(details('查看依據與條件',extra));s.append(article);}return s;}
  target.append(section('結論',result.summary));const branches=node('div',undefined,'research-columns');branches.append(section('敘事動能',result.narrative),details('價格動能 · 無可用資料',[node('p','缺少可驗證的行情版本，未計算報酬或價格動能。')]));target.append(branches,section('支持',result.support),section('反證',result.counter));
  target.append(details('資料缺口與解析條件',[...result.gaps.map(g=>node('p',g)),node('p','資料截止：'+b.lens.time_spec.as_of),...b.lens.interpretation_notes.map(g=>node('p',g)),node('p',`入選 ${b.manifest.selected_count} / ${b.manifest.candidate_count} 個觀點${b.manifest.truncated?'；結果已截斷':''}`),node('p','模型輸出的引用與格式已檢查；語意支持仍需研究者核對。')]));
  const chain=details('研究圖譜',[node('p','點擊 L2 結論、L1 觀點或新聞節點檢視來源。')]);const canvas=node('div',undefined,'research-graph');chain.append(canvas);target.append(chain);chain.addEventListener('toggle',()=>{if(!chain.open||graph||!window.ForceGraph3D)return;const nodes=[],links=[];for(const c of result.claims){nodes.push({id:c.id,title:c.statement,kind:'L2'});for(const ref of c.derived_from)links.push({source:c.id,target:ref,type:'DERIVED_FROM'});}for(const o of b.opinions){nodes.push({id:o.claim_id,title:o.title,kind:'L1'});for(const e of o.evidence){if(!nodes.some(n=>n.id===e.revision_id))nodes.push({id:e.revision_id,title:e.quote,kind:'News'});links.push({source:o.claim_id,target:e.revision_id,type:'SUPPORTED_BY'});}}
  graph=ForceGraph3D()(canvas).width(canvas.clientWidth).height(380).backgroundColor('#09131e').nodeLabel(n=>node('span',n.title).outerHTML).nodeColor(n=>({L2:'#bb9fe4',L1:'#7de3bd',News:'#7db6f2'})[n.kind]).linkLabel('type').graphData({nodes,links}).onNodeClick(n=>{const d=$('researchGraphDetail')||node('p');d.id='researchGraphDetail';d.textContent=n.kind+' · '+n.title;chain.append(d);});});
  const selected=details('入選的 L1 觀點',b.opinions.map(o=>details(o.title,[node('p',o.statement),node('p',o.selection_reason+' · '+(o.labels.join('、')||'未分類，全文可召回'))])));target.append(selected);
 }
 async function loadRun(id,token=serial){const r=await api('run?id='+encodeURIComponent(id));if(token!==serial||panel.hidden)return;runId=id;render(r);}
 async function watch(job,token){clearTimeout(timer);if(token!==serial||panel.hidden)return;try{const j=await api('job?id='+job);if(token!==serial)return;if(j.status==='completed'){await loadRun(j.payload.run_id,token);if(token!==serial||panel.hidden)return;status('研究完成');$('researchSubmit').disabled=false;await saved();}else if(['failed','interrupted','cancelled'].includes(j.status)){status('研究未完成：'+(j.error||j.status)+'。原有結果已保留。');$('researchSubmit').disabled=false;}else{status(j.status==='queued'?'等待模型工作槽…':'正在整合觀點與反證…');timer=setTimeout(()=>watch(job,token),2500);}}catch(e){if(token===serial){status(e.message);$('researchSubmit').disabled=false;}}}
 async function saved(){const token=serial;const r=await api('lenses');if(token!==serial)return;const list=$('researchSaved');list.replaceChildren();if(!r.lenses.length)list.append(node('p','尚未保存研究。'));for(const s of r.lenses){const item=node('section');item.append(action(s.lens.query,async()=>{const token=serial;lastLens=s;await loadRun(s.run_id,token);if(token!==serial||panel.hidden)return;status(({fresh:'已更新',stale:'有新資料，待刷新',failed:'更新失敗，保留前版',pinned:'固定快照'})[s.refresh_state]);}),node('small',s.mode==='pinned'?'固定快照':({fresh:'已更新',stale:'待更新',failed:'更新失敗'})[s.refresh_state]||s.refresh_state));if(s.mode==='live')item.append(action('更新',async()=>{const token=serial;const j=await api('refresh',{lens_id:s.id,expected_revision:s.revision});if(token!==serial)return;if(j.status==='unchanged'){status('已檢查，相關證據沒有改變；未呼叫模型。');await saved();}else watch(j.job_id,token);}));if(s.history.length>1)item.append(action('比較上一版',async()=>{const token=serial;const [current,previous]=await Promise.all([api('run?id='+encodeURIComponent(s.run_id)),api('run?id='+encodeURIComponent(s.history[s.history.length-2]))]);if(token!==serial)return;await loadRun(s.run_id,token);if(token!==serial||panel.hidden)return;const before=new Set(previous.result.claims.map(c=>c.statement)),after=new Set(current.result.claims.map(c=>c.statement));const diff=details('與上一版比較',[node('p','新增／修訂的結論：'),...current.result.claims.filter(c=>!before.has(c.statement)).map(c=>node('p',c.statement)),node('p','不再出現在目前結果：'),...previous.result.claims.filter(c=>!after.has(c.statement)).map(c=>node('p',c.statement))]);diff.open=true;$('researchResult').prepend(diff);}),details('歷史版本',s.history.slice().reverse().map((id,i)=>action(i===0?'目前版本':'較早版本 '+(s.history.length-i),()=>loadRun(id)))));list.append(item);}}
 async function terms(){const token=serial,t=await api('taxonomy');if(token!==serial)return;const list=$('researchTaxonomy');list.replaceChildren();for(const term of t.terms){const label=node('label','定義');const definition=node('input');definition.value=term.definition;label.append(definition);const excludes=node('input');excludes.value=term.exclude.join(', ');excludes.setAttribute('aria-label','排除文字規則');const excludeLabel=node('label','排除文字規則（逗號分隔）');excludeLabel.append(excludes);const aliases=node('input');aliases.value=term.aliases.join(', ');aliases.setAttribute('aria-label',term.label+' 別名');list.append(details(term.label,[label,aliases,excludeLabel,action('儲存分類',async()=>{const updated=structuredClone(t.terms);const edited=updated.find(x=>x.id===term.id);edited.definition=definition.value;edited.exclude=excludes.value.split(',').map(x=>x.trim()).filter(Boolean);edited.aliases=aliases.value.split(',').map(x=>x.trim()).filter(Boolean);await api('taxonomy',{expected_revision:t.revision_id,terms:updated});status('分類已更新，相關研究將重新檢索。');await terms();await saved();})]));}}
 open.onclick=async()=>{const next=$('wikiInstrument').value;if(next!==stock){runId=null;lastLens=null;$('researchSaved').replaceChildren();$('researchTaxonomy').replaceChildren();$('researchResult').replaceChildren(node('p','輸入問題，從這檔股票的 L1 開始研究。'));$('researchQuestion').value='';status('');}stock=next;serial++;clearTimeout(timer);$('researchSubmit').disabled=false;panel.hidden=false;$('researchStock').textContent=stock;$('researchModel').textContent='模型：'+($('wikiModel').selectedOptions[0]?.textContent||'gpt-6.1-sol · high');try{await saved();await terms();}catch(e){status(e.message);}$('researchQuestion').focus();};
 $('researchBack').onclick=()=>{panel.hidden=true;serial++;$('researchSubmit').disabled=false;clearTimeout(timer);graph?._destructor?.();graph=null;};
 $('researchForm').onsubmit=async e=>{e.preventDefault();const token=++serial;$('researchSubmit').disabled=true;status('準備研究條件與證據…');try{const filters=[];for(const [id,exclude] of [['researchInclude',false],['researchExclude',true]]){const value=$(id).value.trim();if(value){const leaf={op:'text',value};filters.push(exclude?{op:'not',arg:leaf}:leaf);}}const [model,reasoning_effort]=($('wikiModel').value||'gpt-6.1-sol|high').split('|');const j=await api('query',{query:$('researchQuestion').value,lookback_days:Number($('researchWindow').value),filter_ast:filters.length?{op:'and',args:filters}:null,model,reasoning_effort});if(token!==serial)return;watch(j.job_id,token);}catch(error){if(token===serial){status(error.message);$('researchSubmit').disabled=false;}}};
})();
